## **4. Transition Plan Generation Logic**
### **4.1 Plan Generation Workflow**
```mermaid
flowchart TD
    A[Household Flagged by HCRDS] --> B[Retrieve Household Data]
    B --> C[Calculate Baseline Metrics]
    C --> D[Determine Risk Level]
    D --> E[Select Transition Template]
    E --> F[Customize Plan]
    F --> G[Generate Phases]
    G --> H[Define Checkpoints]
    H --> I[Assign Coordinator]
    I --> J[Notify Household]
    J --> K[Activate Plan]
```

### **4.2 Plan Customization Rules**
| **HCR Risk Level** | **Placement Schedule** | **Caregiver Rotation Cadence** | **Contact Windows** | **Checkpoint Frequency** |
|--------------------|------------------------|--------------------------------|---------------------|--------------------------|
| **MODERATE (21-40)** | Gradual introduction of **1 new group activity/week** | **Biweekly rotation** (1 new caregiver every 2 weeks) | **Flexible** (existing + 1 new window) | **Biweekly** |
| **HIGH (41-60)** | **2 group activities/week** + **1 new caregiver placement** | **Weekly rotation** (1 new caregiver/week) | **Structured** (3 fixed windows) | **Weekly** |
| **CRITICAL (61-80)** | **Daily group activities** + **2 new caregiver placements** | **Accelerated rotation** (2 new caregivers/week) | **Restricted** (2 fixed windows, no ad-hoc contact) | **Twice weekly** |
| **EXTREME (81-100)** | **Full-time group care** (temporary) | **Immediate rotation** (3+ new caregivers) | **Supervised only** (pre-approved methods) | **Daily** |

### **4.3 Phase Generation Algorithm**
```python
def generate_phases(household, hcr_score):
    phases = []
    baseline = household.baseline

    # Phase 1: Initial Adaptation (Weeks 1-4)
    phase1 = {
        "name": "Initial Adaptation",
        "duration": "P28D",  # 4 weeks
        "placementSchedule": {
            "recurringPlacements": [
                # Retain 80% of existing placements
                *baseline.currentPlacementSchedule.recurringPlacements[:int(0.8 * len(baseline.currentPlacementSchedule.recurringPlacements))]
            ],
            "flexibilityRules": {
                "maxConsecutiveDaysWithSameCaregiver": 5,
                "minUniqueCaregiversPerWeek": 2
            }
        },
        "caregiverRotation": {
            "cadence": "BIWEEKLY" if hcr_score <= 60 else "WEEKLY",
            "rotationGroup": get_eligible_caregivers(household, exclude=baseline.caregiverDependence.topCaregivers),
            "transitionProtocol": {
                "introductionMethod": "GRADUAL",
                "handoffRequirements": {
                    "minVerifyingCaregivers": 2,
                    "preHandoffBriefing": True,
                    "postHandoffCheckIn": "PT2H"  # 2 hours
                }
            }
        },
        "approvedContactWindows": generate_contact_windows(household, hcr_score),
        "messagingTemplates": get_templates_for_phase("INITIAL_ADAPTATION"),
        "participationCheckpoints": generate_checkpoints("INITIAL_ADAPTATION", hcr_score)
    }
    phases.append(phase1)

    # Phase 2: Expanded Integration (Weeks 5-8)
    phase2 = {
        "name": "Expanded Integration",
        "duration": "P28D",
        "placementSchedule": {
            "recurringPlacements": [
                # Retain 50% of existing placements + add group activities
                *baseline.currentPlacementSchedule.recurringPlacements[:int(0.5 * len(baseline.currentPlacementSchedule.recurringPlacements))],
                {
                    "type": "GROUP_ACTIVITY",
                    "facilityId": get_nearest_group_facility(household),
                    "startTime": "09:00:00Z",
                    "endTime": "12:00:00Z",
                    "frequency": "WEEKLY"
                }
            ],
            "flexibilityRules": {
                "maxConsecutiveDaysWithSameCaregiver": 3,
                "minUniqueCaregiversPerWeek": 3
            }
        },
        "caregiverRotation": {
            "cadence": "WEEKLY",
            "rotationGroup": get_eligible_caregivers(household, min_diversity_score=0.7),
            "transitionProtocol": {
                "introductionMethod": "SUPERVISED",
                "handoffRequirements": {
                    "minVerifyingCaregivers": 1,
                    "preHandoffBriefing": True,
                    "postHandoffCheckIn": "PT1H"
                }
            }
        },
        "approvedContactWindows": generate_contact_windows(household, hcr_score, phase=2),
        "messagingTemplates": get_templates_for_phase("EXPANDED_INTEGRATION"),
        "participationCheckpoints": generate_checkpoints("EXPANDED_INTEGRATION", hcr_score)
    }
    phases.append(phase2)

    # Phase 3: Full Diversification (Weeks 9-12)
    phase3 = {
        "name": "Full Diversification",
        "duration": "P28D",
        "placementSchedule": {
            "recurringPlacements": [
                # Only 20% of original placements + multiple group activities
                *baseline.currentPlacementSchedule.recurringPlacements[:int(0.2 * len(baseline.currentPlacementSchedule.recurringPlacements))],
                {
                    "type": "GROUP_ACTIVITY",
                    "facilityId": get_nearest_group_facility(household),
                    "startTime": "09:00:00Z",
                    "endTime": "12:00:00Z",
                    "frequency": "BIWEEKLY"
                },
                {
                    "type": "GROUP_ACTIVITY",
                    "facilityId": get_secondary_group_facility(household),
                    "startTime": "13:00:00Z",
                    "endTime": "15:00:00Z",
                    "frequency": "WEEKLY"
                }
            ],
            "flexibilityRules": {
                "maxConsecutiveDaysWithSameCaregiver": 2,
                "minUniqueCaregiversPerWeek": 4
            }
        },
        "caregiverRotation": {
            "cadence": "WEEKLY",
            "rotationGroup": get_eligible_caregivers(household, min_diversity_score=0.9),
            "transitionProtocol": {
                "introductionMethod": "IMMEDIATE",
                "handoffRequirements": {
                    "minVerifyingCaregivers": 1,
                    "preHandoffBriefing": False,
                    "postHandoffCheckIn": "PT30M"
                }
            }
        },
        "approvedContactWindows": generate_contact_windows(household, hcr_score, phase=3),
        "messagingTemplates": get_templates_for_phase("FULL_DIVERSIFICATION"),
        "participationCheckpoints": generate_checkpoints("FULL_DIVERSIFICATION", hcr_score)
    }
    phases.append(phase3)

    return phases
```

### **4.4 Contact Window Generation**
```python
def generate_contact_windows(household, hcr_score, phase=1):
    windows = []
    baseline = household.baseline

    # Always include existing preferred methods
    for method in baseline.communicationPatterns.preferredContactMethods:
        windows.append({
            "windowId": str(uuid.uuid4()),
            "dayOfWeek": "ANY",
            "startTime": "08:00",
            "endTime": "20:00",
            "allowedMethods": [method],
            "notes": "Existing preferred method"
        })

    # Add structured windows based on HCR score
    if hcr_score >= 61:  # CRITICAL or EXTREME
        windows = [
            {
                "windowId": str(uuid.uuid4()),
                "dayOfWeek": "MON",
                "startTime": "10:00",
                "endTime": "12:00",
                "allowedMethods": ["PORTAL", "PHONE"],
                "maxDurationMinutes": 30,
                "notes": "Supervised contact window"
            },
            {
                "windowId": str(uuid.uuid4()),
                "dayOfWeek": "THU",
                "startTime": "14:00",
                "endTime": "16:00",
                "allowedMethods": ["PORTAL", "EMAIL"],
                "maxDurationMinutes": 30,
                "notes": "Supervised contact window"
            }
        ]
    elif hcr_score >= 41:  # HIGH
        windows.extend([
            {
                "windowId": str(uuid.uuid4()),
                "dayOfWeek": "WED",
                "startTime": "09:00",
                "endTime": "11:00",
                "allowedMethods": ["PORTAL", "PHONE", "IN_PERSON"],
                "notes": "Structured contact window"
            }
        ])
    else:  # MODERATE
        windows.extend([
            {
                "windowId": str(uuid.uuid4()),
                "dayOfWeek": "SAT",
                "startTime": "10:00",
                "endTime": "14:00",
                "allowedMethods": ["PHONE", "IN_PERSON"],
                "notes": "Flexible additional window"
            }
        ])

    return windows
```

