def generate_checkpoints(phase_name, hcr_score):
    checkpoints = []

    if phase_name == "INITIAL_ADAPTATION":
        checkpoints = [
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "PLACEMENT_ATTENDANCE",
                "description": "Attend first group activity placement",
                "dueDate": "P7D",  # 7 days from phase start
                "passingCriteria": {
                    "minAdherencePercentage": 100,
                    "requiredActions": ["attend placement"]
                }
            },
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "CAREGIVER_INTERACTION",
                "description": "Positive interaction with new caregiver",
                "dueDate": "P14D",
                "passingCriteria": {
                    "minAdherencePercentage": 100,
                    "requiredActions": ["interact with new caregiver", "positive sentiment"]
                }
            }
        ]
    elif phase_name == "EXPANDED_INTEGRATION":
        checkpoints = [
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "PLACEMENT_ATTENDANCE",
                "description": "Attend all scheduled placements for 2 weeks",
                "dueDate": "P14D",
                "passingCriteria": {
                    "minAdherencePercentage": 90,
                    "requiredActions": ["attend placement"]
                }
            },
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "CONTACT_WINDOW_ADHERENCE",
                "description": "Adhere to approved contact windows",
                "dueDate": "P14D",
                "passingCriteria": {
                    "minAdherencePercentage": 80,
                    "requiredActions": ["use approved methods", "stay within time windows"]
                }
            },
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "FEEDBACK_SUBMISSION",
                "description": "Submit feedback on transition experience",
                "dueDate": "P14D",
                "passingCriteria": {
                    "minAdherencePercentage": 100,
                    "requiredActions": ["submit feedback"]
                }
            }
        ]
    elif phase_name == "FULL_DIVERSIFICATION":
        checkpoints = [
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "PLACEMENT_ATTENDANCE",
                "description": "Attend all placements with <10% absences",
                "dueDate": "P28D",
                "passingCriteria": {
                    "minAdherencePercentage": 90,
                    "requiredActions": ["attend placement"]
                }
            },
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "CAREGIVER_INTERACTION",
                "description": "Interact with at least 3 unique caregivers",
                "dueDate": "P28D",
                "passingCriteria": {
                    "minAdherencePercentage": 100,
                    "requiredActions": ["interact with 3+ caregivers"]
                }
            },
            {
                "checkpointId": str(uuid.uuid4()),
                "type": "CONTACT_WINDOW_ADHERENCE",
                "description": "100% adherence to contact windows",
                "dueDate": "P28D",
                "passingCriteria": {
                    "minAdherencePercentage": 100,
                    "requiredActions": ["strict adherence to windows"]
                }
            }
        ]

    # Add more frequent checkpoints for higher HCR scores
    if hcr_score >= 81:  # EXTREME
        for checkpoint in checkpoints:
            checkpoint["dueDate"] = "P7D"  # Shorten deadline
        checkpoints.append({
            "checkpointId": str(uuid.uuid4()),
            "type": "FEEDBACK_SUBMISSION",
            "description": "Weekly feedback submission",
            "dueDate": "P7D",
            "passingCriteria": {
                "minAdherencePercentage": 100,
                "requiredActions": ["submit feedback"]
            }
        })

    return checkpoints
