  "script_id": "SCRIPT-12345",
  "customer_id": "CUST-67890",
  "cohort": "at_risk_low_steadiness",  // CSS tier + risk segment
  "generated_at": "2023-11-20T14:30:00Z",
  "expiry": "2023-12-20T14:30:00Z",     // Script validity period
  "steadiness_target": {
    "min_spend": 150.00,                // Weekly target derived from CSS
    "min_purchase_frequency": 2,       // Purchases/week
    "allowed_categories": ["comfort", "staples"]
  },
  "craving_triggers": [
    {
      "trigger_id": "TRIG-001",
      "type": "time_based",             // time_based | location_based | behavioral
